# 50,000 data in string list
# insertion sort
# time-taken
def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1

        arr[j + 1] = key
        
from faker import Faker
def generate_fake_names(count=5000):
    fake = Faker()
    return [fake.name() for _ in range(count)]

